alter table dm_private.exam_mock_blueprints add column structure_version text,add column section_manifest jsonb;
update dm_private.exam_mock_blueprints set question_count=57,duration_seconds=7200,structure_version='iitb-2027-v1',section_manifest='{"label":"Part A","counts":{"nat":14,"msq":15,"mcq":28}}' where exam='uceed';
update dm_private.exam_mock_blueprints set question_count=44,duration_seconds=3600,structure_version='iitb-2027-v1',section_manifest='{"label":"Part A","counts":{"nat":8,"msq":10,"mcq":26}}' where exam='ceed';
alter table dm_private.exam_mock_blueprints add constraint verified_exam_manifest check((exam='uceed'and question_count=57 and duration_seconds=7200 and structure_version='iitb-2027-v1'and section_manifest='{"label":"Part A","counts":{"nat":14,"msq":15,"mcq":28}}'::jsonb)or(exam='ceed'and question_count=44 and duration_seconds=3600 and structure_version='iitb-2027-v1'and section_manifest='{"label":"Part A","counts":{"nat":8,"msq":10,"mcq":26}}'::jsonb)or(exam in('nid','nift')and structure_version is null and section_manifest is null));
create or replace function dm_private.exam_blueprint_ready(p_exam text,p_count integer,p_manifest jsonb)returns boolean language sql stable set search_path=pg_catalog,dm_private as $$select case when p_manifest is null then(select count(*)>=p_count from dm_private.bank_questions q where q.exam=p_exam and q.active and q.owner_approved and q.rights_confirmed and q.runtime_payload is not null)else not exists(select 1 from jsonb_each_text(p_manifest->'counts')required where(select count(*)from dm_private.bank_questions q where q.exam=p_exam and q.active and q.owner_approved and q.rights_confirmed and q.runtime_payload is not null and q.runtime_payload->>'kind'=required.key)<required.value::integer)end$$;
create or replace function public.admin_exam_mock_blueprints()returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,dm_private as $$begin if not public.is_dmocks_admin()then raise exception'Admin access required';end if;return(select jsonb_agg(jsonb_build_object('exam',b.exam,'questionCount',b.question_count,'durationSeconds',b.duration_seconds,'freeAttemptLimit',b.free_attempt_limit,'enabled',b.enabled,'structureVersion',b.structure_version,'sectionLabel',b.section_manifest->>'label','sectionCounts',b.section_manifest->'counts','ready',dm_private.exam_blueprint_ready(b.exam,b.question_count,b.section_manifest),'reviewedQuestions',(select count(*)from dm_private.bank_questions q where q.exam=b.exam and q.active and q.owner_approved and q.rights_confirmed and q.runtime_payload is not null))order by b.exam)from dm_private.exam_mock_blueprints b);end$$;
create or replace function public.admin_configure_exam_mock(p_exam text,p_question_count integer,p_duration_seconds integer,p_free_attempt_limit integer,p_enabled boolean)returns void language plpgsql security definer set search_path=pg_catalog,public,dm_private as $$declare b dm_private.exam_mock_blueprints;begin if not public.is_dmocks_admin()then raise exception'Admin access required';end if;select*into b from dm_private.exam_mock_blueprints where exam=lower(p_exam)for update;if b.exam is null then raise exception'Unknown exam';end if;if b.structure_version is not null and(p_question_count<>b.question_count or p_duration_seconds<>b.duration_seconds)then raise exception'Verified exam structure is fixed';end if;if p_enabled and not dm_private.exam_blueprint_ready(b.exam,p_question_count,b.section_manifest)then raise exception'Not enough reviewed questions for every required section';end if;update dm_private.exam_mock_blueprints set question_count=p_question_count,duration_seconds=p_duration_seconds,free_attempt_limit=p_free_attempt_limit,enabled=p_enabled,updated_by=auth.uid(),updated_at=now()where exam=b.exam;end$$;
create or replace function public.exam_mock_catalog()returns jsonb language plpgsql stable security definer set search_path=pg_catalog,dm_private as $$begin if auth.uid()is null then raise exception'Sign in required';end if;return(select jsonb_agg(jsonb_build_object('exam',b.exam,'questionCount',b.question_count,'durationSeconds',b.duration_seconds,'freeAttemptLimit',b.free_attempt_limit,'freeAttemptsUsed',(select count(*)from dm_private.attempts a join dm_private.papers p on p.id=a.paper_id where a.user_id=auth.uid()and p.source_kind='exam'and p.exam=b.exam),'enabled',b.enabled,'structureVersion',b.structure_version,'sectionLabel',b.section_manifest->>'label','sectionCounts',b.section_manifest->'counts','ready',b.enabled and dm_private.exam_blueprint_ready(b.exam,b.question_count,b.section_manifest))order by b.exam)from dm_private.exam_mock_blueprints b);end$$;
create or replace function public.start_exam_mock(p_exam text)returns uuid language plpgsql security definer set search_path=pg_catalog,public,dm_private as $$declare b dm_private.exam_mock_blueprints;v_mode text;v_paid boolean;v_used integer;v_paper uuid;v_attempt uuid;v_question_id uuid;v_seed uuid:=gen_random_uuid();v_question record;v_section record;v_ordinal integer:=0;begin if auth.uid()is null then raise exception'Sign in required';end if;perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text,2));select*into b from dm_private.exam_mock_blueprints where exam=lower(p_exam)and enabled;if b.exam is null then raise exception'This exam mock is not released';end if;if not exists(select 1 from public.profiles where user_id=auth.uid()and onboarding_completed_at is not null)then raise exception'Complete your verified profile first';end if;select environment_mode into v_mode from public.launch_settings where singleton;select exists(select 1 from dm_private.passes where user_id=auth.uid()and mode=v_mode and expires_at>now())into v_paid;select count(*)into v_used from dm_private.attempts a join dm_private.papers p on p.id=a.paper_id where a.user_id=auth.uid()and p.source_kind='exam'and p.exam=b.exam;if not v_paid and v_used>=b.free_attempt_limit then raise exception'An active pass is required';end if;if(select count(*)from dm_private.attempts where user_id=auth.uid()and status='active'and deadline>now())>=3 then raise exception'Finish an active attempt before starting another';end if;if not dm_private.exam_blueprint_ready(b.exam,b.question_count,b.section_manifest)then raise exception'Not enough reviewed questions for every required section';end if;insert into dm_private.papers(title,exam,duration_seconds,published,reviewed,rights_confirmed,owner_user_id,source_kind)values(upper(b.exam)||case when b.section_manifest is null then' exam-wise mock'else' 2027 '||(b.section_manifest->>'label')||' mock'end,b.exam,b.duration_seconds,false,true,true,auth.uid(),'exam')returning id into v_paper;if b.section_manifest is null then for v_question in select*from dm_private.bank_questions where exam=b.exam and active and owner_approved and rights_confirmed and runtime_payload is not null order by md5(external_key||v_seed::text)limit b.question_count loop v_ordinal:=v_ordinal+1;insert into dm_private.questions(paper_id,ordinal,prompt,options,kind,marking,media,points,negative_points,topic,reviewed)values(v_paper,v_ordinal,v_question.runtime_payload->>'prompt',v_question.runtime_payload->'options',v_question.runtime_payload->>'kind',v_question.runtime_payload->'marking',v_question.runtime_payload->'media',(v_question.runtime_payload->>'points')::numeric,(v_question.runtime_payload->>'negativePoints')::numeric,v_question.topic,true)returning id into v_question_id;insert into dm_private.answer_keys(question_id,key,explanation)values(v_question_id,v_question.runtime_payload->'key',v_question.runtime_payload->>'explanation');end loop;else for v_section in select key,value::integer required_count from jsonb_each_text(b.section_manifest->'counts')order by case key when'nat'then 1 when'msq'then 2 when'mcq'then 3 end loop for v_question in select*from dm_private.bank_questions where exam=b.exam and active and owner_approved and rights_confirmed and runtime_payload is not null and runtime_payload->>'kind'=v_section.key order by md5(external_key||v_seed::text)limit v_section.required_count loop v_ordinal:=v_ordinal+1;insert into dm_private.questions(paper_id,ordinal,prompt,options,kind,marking,media,points,negative_points,topic,reviewed)values(v_paper,v_ordinal,v_question.runtime_payload->>'prompt',v_question.runtime_payload->'options',v_question.runtime_payload->>'kind',v_question.runtime_payload->'marking',v_question.runtime_payload->'media',(v_question.runtime_payload->>'points')::numeric,(v_question.runtime_payload->>'negativePoints')::numeric,v_question.topic,true)returning id into v_question_id;insert into dm_private.answer_keys(question_id,key,explanation)values(v_question_id,v_question.runtime_payload->'key',v_question.runtime_payload->>'explanation');end loop;end loop;end if;if v_ordinal<>b.question_count then raise exception'Frozen paper does not match verified manifest';end if;insert into dm_private.attempts(user_id,paper_id,deadline)values(auth.uid(),v_paper,now()+make_interval(secs=>b.duration_seconds))returning id into v_attempt;insert into dm_private.attempt_items(attempt_id,question_id,ordinal,prompt,options,points,negative_points,topic,kind,marking,media,key,explanation)select v_attempt,q.id,q.ordinal,q.prompt,q.options,q.points,q.negative_points,q.topic,q.kind,q.marking,q.media,k.key,k.explanation from dm_private.questions q join dm_private.answer_keys k on k.question_id=q.id where q.paper_id=v_paper;return v_attempt;end$$;
